mapper.insert:
INSERT INTO SATISFACTION (
  SCHEDULE_NO
  , ENGINEER_NO
  , SCORE_VISIT
  , SCORE_KINDNESS
  , SCORE_RESULT
  , COMMENT_TEXT
)
VALUES (
  #{scheduleNo}
  , #{engineerNo}
  , #{scoreVisit}
  , #{scoreKindness}
  , #{scoreResult}
  , #{commentText}
);

mapper.select:
SELECT ROUND(AVG((SCORE_VISIT + SCORE_KINDNESS + SCORE_RESULT) / 3.0), 1)
FROM SATISFACTION
WHERE ENGINEER_NO = #{engineerNo}
AND YEAR(CREATED_AT) = #{year}
AND MONTH(CREATED_AT) = #{month};

SELECT MONTH(CREATED_AT) AS month
, ROUND(AVG((SCORE_VISIT + SCORE_KINDNESS + SCORE_RESULT) / 3.0), 1) AS avgScore
, COUNT(*) AS count
FROM SATISFACTION
WHERE ENGINEER_NO = #{engineerNo}
AND YEAR(CREATED_AT) = #{year}
GROUP BY MONTH(CREATED_AT)
ORDER BY month;
